//! Groth16 codec and verification against a real snarkjs proof (test-vectors/protocol/groth16,
//! generated by scripts/protocol-groth16-vectors.sh).
use galaxy_crypto::field::fr_from_dec;
use galaxy_crypto::groth16::{public_from_snarkjs_json, verify, Groth16Error, Proof, VerifyingKey};
use galaxy_crypto::Fr;
use serde::Deserialize;

const DIR: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../../test-vectors/protocol/groth16/");

#[derive(Deserialize)]
struct Vectors {
    n_public: usize,
    cases: Vec<Case>,
}

#[derive(Deserialize)]
struct Case {
    name: String,
    proof_hex: String,
    vk_hex: String,
    public: Vec<String>,
    expect: String,
}

fn file(name: &str) -> Vec<u8> {
    std::fs::read(format!("{DIR}{name}")).unwrap()
}

fn vectors() -> Vectors {
    serde_json::from_slice(&file("vectors.json")).unwrap()
}

fn variant(err: &Groth16Error) -> &'static str {
    match err {
        Groth16Error::Length { .. } => "Length",
        Groth16Error::VkHeader => "VkHeader",
        Groth16Error::PublicCount => "PublicCount",
        Groth16Error::NonCanonical => "NonCanonical",
        Groth16Error::Infinity => "Infinity",
        Groth16Error::NotOnCurve => "NotOnCurve",
        Groth16Error::NotInSubgroup => "NotInSubgroup",
        Groth16Error::Json(_) => "Json",
        Groth16Error::PublicInputs { .. } => "PublicInputs",
    }
}

fn run(case: &Case) -> String {
    let vk = match VerifyingKey::from_bytes(&hex::decode(&case.vk_hex).unwrap()) {
        Ok(vk) => vk,
        Err(e) => return format!("error:{}", variant(&e)),
    };
    let proof = match Proof::from_bytes(&hex::decode(&case.proof_hex).unwrap()) {
        Ok(proof) => proof,
        Err(e) => return format!("error:{}", variant(&e)),
    };
    let public: Result<Vec<Fr>, _> = case.public.iter().map(|s| fr_from_dec(s)).collect();
    let Ok(public) = public else { return "error:Scalar".into() };
    match verify(&vk, &public, &proof) {
        Ok(ok) => format!("verify:{ok}"),
        Err(e) => format!("error:{}", variant(&e)),
    }
}

#[test]
fn vector_cases() {
    let vectors = vectors();
    assert!(vectors.cases.len() >= 20);
    for case in &vectors.cases {
        assert_eq!(run(case), case.expect, "{}", case.name);
    }
}

#[test]
fn snarkjs_json_import_matches_independent_byte_encoding() {
    let vectors = vectors();
    let valid = &vectors.cases[0];
    assert_eq!(valid.name, "valid");
    let vk = VerifyingKey::from_snarkjs_json(&file("verification_key.json")).unwrap();
    let proof = Proof::from_snarkjs_json(&file("proof.json")).unwrap();
    let public = public_from_snarkjs_json(&file("public.json")).unwrap();
    assert_eq!(vk.n_public(), vectors.n_public);
    assert_eq!(hex::encode(vk.to_bytes()), valid.vk_hex);
    assert_eq!(hex::encode(proof.to_bytes()), valid.proof_hex);
    assert!(verify(&vk, &public, &proof).unwrap());
    // Byte round trips.
    assert_eq!(VerifyingKey::from_bytes(&vk.to_bytes()).unwrap(), vk);
    assert_eq!(Proof::from_bytes(&proof.to_bytes()).unwrap(), proof);
    // Wrapping arkworks values keeps the same encodings.
    assert_eq!(VerifyingKey::from_ark(vk.as_ark().clone()).unwrap().to_bytes(), vk.to_bytes());
    assert_eq!(Proof::from_ark(proof.as_ark().clone()).unwrap().to_bytes(), proof.to_bytes());
}

#[test]
fn snarkjs_json_negative_cases() {
    let proof: serde_json::Value = serde_json::from_slice(&file("proof.json")).unwrap();
    let vk: serde_json::Value = serde_json::from_slice(&file("verification_key.json")).unwrap();
    let proof_err = |v: &serde_json::Value| Proof::from_snarkjs_json(v.to_string().as_bytes()).unwrap_err();
    let vk_err = |v: &serde_json::Value| VerifyingKey::from_snarkjs_json(v.to_string().as_bytes()).unwrap_err();

    let mut flipped = proof.clone();
    for coordinate in 0..2 {
        flipped["pi_b"][coordinate].as_array_mut().unwrap().swap(0, 1);
    }
    assert_eq!(proof_err(&flipped), Groth16Error::NotOnCurve);
    let mut z = proof.clone();
    z["pi_a"][2] = "2".into();
    assert!(matches!(proof_err(&z), Groth16Error::Json(_)));
    let mut leading_zero = proof.clone();
    leading_zero["pi_a"][0] = format!("0{}", proof["pi_a"][0].as_str().unwrap()).into();
    assert!(matches!(proof_err(&leading_zero), Groth16Error::Json(_)));
    let mut protocol = proof.clone();
    protocol["protocol"] = "plonk".into();
    assert!(matches!(proof_err(&protocol), Groth16Error::Json(_)));
    let mut ge_q = proof.clone();
    ge_q["pi_c"][1] = "21888242871839275222246405745257275088696311157297823662689037894645226208583".into();
    assert_eq!(proof_err(&ge_q), Groth16Error::NonCanonical);

    let mut n_public = vk.clone();
    n_public["nPublic"] = (vk["nPublic"].as_u64().unwrap() + 1).into();
    assert_eq!(vk_err(&n_public), Groth16Error::PublicCount);
    let mut curve = vk.clone();
    curve["curve"] = "bls12381".into();
    assert!(matches!(vk_err(&curve), Groth16Error::Json(_)));
    let mut gamma = vk.clone();
    gamma["vk_gamma_2"][0].as_array_mut().unwrap().swap(0, 1);
    gamma["vk_gamma_2"][1].as_array_mut().unwrap().swap(0, 1);
    assert_eq!(vk_err(&gamma), Groth16Error::NotOnCurve);

    assert!(public_from_snarkjs_json(b"[\"01\"]").is_err());
    assert!(public_from_snarkjs_json(b"[1]").is_err());
    assert!(public_from_snarkjs_json(
        b"[\"21888242871839275222246405745257275088548364400416034343698204186575808495617\"]"
    )
    .is_err());
}

#[test]
fn decoders_never_panic_on_mutations() {
    let valid = &vectors().cases[0];
    let proof = hex::decode(&valid.proof_hex).unwrap();
    let vk = hex::decode(&valid.vk_hex).unwrap();
    for len in 0..=vk.len() + 1 {
        let mut bytes = vk.clone();
        bytes.resize(len, 0);
        let _ = VerifyingKey::from_bytes(&bytes);
        let _ = Proof::from_bytes(&bytes[..len.min(proof.len() + 1)]);
    }
    let mut state = 0x2545_f491_4f6c_dd1du64;
    for _ in 0..300 {
        for target in [&proof, &vk] {
            let mut bytes = target.clone();
            state ^= state << 13;
            state ^= state >> 7;
            state ^= state << 17;
            let at = (state % bytes.len() as u64) as usize;
            bytes[at] ^= 1 << (state >> 61);
            let _ = Proof::from_bytes(&bytes);
            let _ = VerifyingKey::from_bytes(&bytes);
        }
    }
    // Huge n_public header must be rejected without allocating.
    let mut huge = vk.clone();
    huge[2..6].copy_from_slice(&u32::MAX.to_be_bytes());
    assert_eq!(VerifyingKey::from_bytes(&huge).unwrap_err(), Groth16Error::PublicCount);
}
